/**
 * Test helper — generates a fake `octocode` executable wrapping
 * `fake-octocode-mcp.mjs`, so adapter tests can run a real MCP stdio session
 * without Octocode installed (no network, no real binary, no writes outside a
 * temp dir).
 *
 * Usage:
 *   const fake = makeFakeOctocode({ mode: "ok" });          // POSIX only
 *   const config = cloneDefault();
 *   config.integrations.octocode.bin = fake.bin;
 *   ...
 *   fake.cleanup();
 *
 * The adapter probes `<bin> --version` (must print `octocode 0.29.2`) and later
 * spawns `<bin> mcp --path <root>`; the wrapper answers the probe and forwards
 * the rest to the fake MCP server with its mode argument.
 *
 * IMPORTANT: the wrapper is a `#!/bin/sh` script, so spawning it only works on
 * POSIX. Tests that execute it must be guarded with
 * `test.skipIf(process.platform === "win32")`; pure parser/degradation tests
 * stay cross-platform.
 */
import { chmodSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

export type FakeOctocodeMode = "ok" | "invalid" | "timeout" | "tools-missing";

export interface FakeOctocodeOptions {
  /** Failure mode the fake MCP server simulates (default "ok"). */
  mode?: FakeOctocodeMode;
  /** Version printed by `<bin> --version` (default tested range: "0.29.2"). */
  version?: string;
}

export interface FakeOctocode {
  /** Absolute path to the generated executable (use as `integrations.octocode.bin`). */
  bin: string;
  mode: FakeOctocodeMode;
  version: string;
  cleanup(): void;
}

const FAKE_SERVER = join(dirname(fileURLToPath(import.meta.url)), "fake-octocode-mcp.mjs");

function shellQuote(value: string): string {
  return `'${value.replaceAll("'", `'\\''`)}'`;
}

/** Create a temp `octocode` executable that speaks the recorded MCP fixtures. */
export function makeFakeOctocode(options: FakeOctocodeOptions = {}): FakeOctocode {
  const mode = options.mode ?? "ok";
  const version = options.version ?? "0.29.2";
  const dir = mkdtempSync(join(tmpdir(), "mygrace-fake-octocode-"));
  const bin = join(dir, "octocode");
  const script = [
    "#!/bin/sh",
    "# Generated by test/fixtures/octocode/fake-octocode.ts — fake Octocode for tests.",
    'if [ "$1" = "--version" ]; then',
    `  echo "octocode ${version}"`,
    "  exit 0",
    "fi",
    `exec ${shellQuote(process.execPath)} ${shellQuote(FAKE_SERVER)} --fake-mode ${shellQuote(mode)} "$@"`,
    "",
  ].join("\n");
  writeFileSync(bin, script, { encoding: "utf-8", mode: 0o755 });
  chmodSync(bin, 0o755);
  return {
    bin,
    mode,
    version,
    cleanup: () => rmSync(dir, { recursive: true, force: true }),
  };
}
